import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { DatabaseSync } from 'node:sqlite'

export const REASON='Approved OCC Frequency Import and Duplicate Schedule Resolution 20260803'
const ACTOR='kcadmin'
const aliases=new Map([['weekly','Once a week'],['twice weekly','Twice a week'],['daily','Daily'],['call','On Call']])
const excludedCodes=new Set(['10018','10240','10241'])
const clean=v=>String(v??'').trim()
const json=v=>v==null?null:JSON.stringify(v)
const parseDays=v=>{if(!clean(v))return[];try{const x=JSON.parse(v);if(Array.isArray(x))return x}catch{}return clean(v).replace(/^\[|\]$/g,'').split(/[,;/]/).map(x=>x.replaceAll('"','').trim()).filter(Boolean)}
const sameDays=(a,b)=>JSON.stringify([...new Set(parseDays(a))].sort())===JSON.stringify([...new Set(parseDays(b))].sort())
const frequency=v=>aliases.get(clean(v).toLowerCase())||null
const audit=(db,type,id,change,field,oldValue,newValue,before,after,sourceRow,detail={})=>db.prepare(`INSERT INTO master_change_history(entity_type,entity_id,change_type,field_name,old_value,new_value,before_json,after_json,reason,changed_by) VALUES(?,?,?,?,?,?,?,?,?,?)`).run(type,String(id),change,field,oldValue??null,newValue??null,json(before),json({...after,excelSourceRow:sourceRow,...detail}),REASON,ACTOR)
const counts=db=>({customers:db.prepare('SELECT COUNT(*) n FROM customers').get().n,branches:db.prepare('SELECT COUNT(*) n FROM branches').get().n,occAssignments:db.prepare('SELECT COUNT(*) n FROM branch_occ_price_assignments').get().n,frequency:db.prepare("SELECT COUNT(*) n FROM branches WHERE collection_frequency IS NOT NULL AND TRIM(collection_frequency)<>''").get().n,weekdays:db.prepare("SELECT COUNT(*) n FROM branches WHERE assigned_weekdays IS NOT NULL AND TRIM(assigned_weekdays)<>''").get().n,schedules:db.prepare('SELECT COUNT(*) n FROM branch_schedules').get().n,activeSchedules:db.prepare('SELECT COUNT(*) n FROM branch_schedules WHERE is_active=1').get().n,dispatches:db.prepare('SELECT COUNT(*) n FROM dispatches').get().n,dispatchStops:db.prepare('SELECT COUNT(*) n FROM dispatch_stops').get().n,audit:db.prepare('SELECT COUNT(*) n FROM master_change_history').get().n,occHistory:db.prepare('SELECT COUNT(*) n FROM branch_occ_price_assignment_history').get().n})
function branch(db,code){return db.prepare(`SELECT b.*,c.jodoo_customer_id customer_code,c.name customer_name,c.is_active customer_active,g.id occ_group_id,g.price_amount occ_price_amount FROM branches b LEFT JOIN customers c ON c.id=b.customer_id LEFT JOIN branch_occ_price_assignments a ON a.branch_id=b.id LEFT JOIN occ_price_groups g ON g.id=a.occ_price_group_id WHERE b.jodoo_branch_id=?`).get(String(code))}
function duplicatePlan(db,decisions=[]){return decisions.map(d=>{const keep=db.prepare('SELECT * FROM branch_schedules WHERE jodoo_schedule_id=?').get(String(d.keep)),drop=db.prepare('SELECT * FROM branch_schedules WHERE jodoo_schedule_id=?').get(String(d.deactivate));if(!keep||!drop)throw new Error(`Duplicate Schedule decision missing: ${d.keep}/${d.deactivate}`);const keys=['branch_id','source_branch_id','frequency','days_of_week','take_date','next_take_date','is_active','source_updated_at','updated_at'];const identical=keys.every(k=>String(keep[k]??'')===String(drop[k]??''));const stopRefs=db.prepare('SELECT COUNT(*) n FROM dispatch_stops WHERE source_schedule_id=?').get(drop.id).n,exceptionRefs=db.prepare('SELECT COUNT(*) n FROM schedule_exceptions WHERE schedule_id=?').get(drop.id).n;return{...d,keepInternalId:keep.id,deactivateInternalId:drop.id,identical,dispatchStopRefs:stopRefs,exceptionRefs,safe:identical&&stopRefs===0&&exceptionRefs===0}})}

export function runCombinedImport(db,input,{apply=false}={}){
  db.exec('PRAGMA foreign_keys=ON');const schema=Number(db.prepare('SELECT MAX(version) v FROM schema_meta').get().v);if(schema!==25)throw new Error(`Expected Schema v25, found v${schema}`);if(db.prepare('PRAGMA integrity_check').get().integrity_check!=='ok')throw new Error('Pre-write integrity_check failed');if(db.prepare('PRAGMA foreign_key_check').all().length)throw new Error('Pre-write foreign_key_check failed')
  const before=counts(db),duplicates=duplicatePlan(db,input.duplicateScheduleDecisions),blockedScheduleBranches=new Set(duplicates.filter(x=>!x.safe).map(x=>String(x.branchId))),rows=[],seen=new Set()
  for(const source of input.rows){const code=clean(source.branchId),row={...source,branchId:code};if(source.scope==='Excluded / Deferred'){row.matchStatus='Excluded';row.occAction='Excluded';row.frequencyAction='Excluded';row.weekdayAction='No Change';row.scheduleAction='Excluded';row.routeEligible=false;row.blockReason=source.note||'Excluded by approved scope';rows.push(row);continue}if(source.scope==='Still Blocked'){row.matchStatus='Blocked';row.occAction='Blocked';row.frequencyAction='Blocked';row.weekdayAction='No Change';row.scheduleAction='Blocked';row.routeEligible=false;row.blockReason=source.note||'Supervisor decision required';rows.push(row);continue}if(!code||seen.has(code)){row.matchStatus='Blocked';row.occAction='Blocked';row.frequencyAction='Blocked';row.weekdayAction='No Change';row.scheduleAction='Blocked';row.routeEligible=false;row.blockReason=!code?'Missing approved Branch ID':'Duplicate input Branch';rows.push(row);continue}seen.add(code);const b=branch(db,code);if(!b){row.matchStatus='Blocked';row.occAction='Blocked';row.frequencyAction='Blocked';row.weekdayAction='No Change';row.scheduleAction='Blocked';row.routeEligible=false;row.blockReason='Approved Branch not found';rows.push(row);continue}row.internalBranchId=b.id;row.customerId=b.customer_code;row.customerName=b.customer_name;row.branchName=b.branch_name;row.currentOccGroupId=b.occ_group_id;row.currentOccPrice=b.occ_price_amount;row.currentFrequency=b.collection_frequency;row.existingWeekdays=b.assigned_weekdays;const excluded=excludedCodes.has(code)||b.is_active!==1||b.status!=='active'||b.customer_active!==1;if(excluded){row.matchStatus='Excluded';row.occAction='Excluded';row.frequencyAction='Excluded';row.weekdayAction='No Change';row.scheduleAction='Excluded';row.routeEligible=false;row.blockReason=source.note||'Excluded by approved scope';rows.push(row);continue}row.matchStatus='Resolved';const target=Number(source.targetOccPrice),group=Number.isFinite(target)?db.prepare("SELECT id,item_code,price_amount FROM occ_price_groups WHERE status='active' AND ABS(price_amount-?)<0.000001").all(target):[];if(!Number.isFinite(target)||group.length!==1){row.occAction='Blocked';row.blockReason='Missing or non-unique OCC target Price Group'}else{row.targetOccGroupId=group[0].id;row.targetOccPrice=group[0].price_amount;row.occAction=b.occ_group_id==null?'Add':Math.abs(Number(b.occ_price_amount)-target)<0.000001?'No Change':'Update'}
    const targetFreq=frequency(source.rawFrequency);row.targetFrequency=targetFreq;if(!targetFreq)row.frequencyAction='Blocked';else if(targetFreq==='On Call'&&parseDays(b.assigned_weekdays).length)row.frequencyAction='Blocked';else row.frequencyAction=clean(b.collection_frequency)===targetFreq?'No Change':clean(b.collection_frequency)?'Update':'Add';row.weekdayAction='No Change';const schedules=db.prepare('SELECT * FROM branch_schedules WHERE branch_id=? AND is_active=1 ORDER BY id').all(b.id),days=parseDays(b.assigned_weekdays);row.activeScheduleCount=schedules.length;if(!days.length){row.scheduleAction='Missing Existing Weekday';row.routeEligible=false}else if(blockedScheduleBranches.has(code)){row.scheduleAction='Blocked Duplicate Schedule';row.routeEligible=false}else if(!targetFreq||targetFreq==='On Call'){row.scheduleAction='Excluded';row.routeEligible=false}else if(schedules.length!==1){row.scheduleAction=schedules.length?'Blocked Multiple Active Schedules':'No Existing Schedule';row.routeEligible=false}else if(!sameDays(schedules[0].days_of_week,b.assigned_weekdays)){row.scheduleAction='Blocked Weekday Conflict';row.routeEligible=false}else{row.scheduleId=schedules[0].jodoo_schedule_id;row.scheduleAction=clean(schedules[0].frequency)===targetFreq?'No Change':'Update Frequency';row.routeEligible=true}rows.push(row)
  }
  const plan={schema,rows,duplicates,summary:{}}
  for(const key of ['occAction','frequencyAction','weekdayAction','scheduleAction'])for(const row of rows){const k=`${key}:${row[key]||'Unclassified'}`;plan.summary[k]=(plan.summary[k]||0)+1}plan.summary.routeEligible=rows.filter(x=>x.routeEligible).length;plan.summary.routeExcluded=rows.length-plan.summary.routeEligible
  if(!apply)return{mode:'dry-run',before,plan,writes:0}
  const write={occUpdated:0,occAdded:0,frequencyUpdated:0,frequencyAdded:0,weekdayWrites:0,scheduleFrequencyUpdated:0,duplicateSchedulesDeactivated:0,auditInserted:0}
  db.exec('BEGIN IMMEDIATE');try{
    for(const row of rows){if(!['Resolved'].includes(row.matchStatus))continue;const b=branch(db,row.branchId);if(['Update','Add'].includes(row.occAction)){if((row.occAction==='Add'&&b.occ_group_id!=null)||(row.occAction==='Update'&&Number(b.occ_group_id)!==Number(row.currentOccGroupId)))throw new Error(`Stale OCC assignment for Branch ${row.branchId}`);db.prepare(`INSERT INTO branch_occ_price_assignments(branch_id,occ_price_group_id,assigned_by) VALUES(?,?,?) ON CONFLICT(branch_id) DO UPDATE SET occ_price_group_id=excluded.occ_price_group_id,assigned_by=excluded.assigned_by,updated_at=CURRENT_TIMESTAMP`).run(b.id,row.targetOccGroupId,ACTOR);db.prepare('INSERT INTO branch_occ_price_assignment_history(branch_id,old_occ_price_group_id,new_occ_price_group_id,reason,changed_by) VALUES(?,?,?,?,?)').run(b.id,b.occ_group_id||null,row.targetOccGroupId,REASON,ACTOR);if(row.occAction==='Add')write.occAdded++;else write.occUpdated++}
      if(['Update','Add'].includes(row.frequencyAction)){const old=b.collection_frequency;db.prepare('UPDATE branches SET collection_frequency=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(row.targetFrequency,b.id);const after=branch(db,row.branchId);audit(db,'branch',row.branchId,'approved_frequency_import','collection_frequency',old,row.targetFrequency,b,after,row.excelRow,{branchId:row.branchId,customerId:row.customerId});if(row.frequencyAction==='Add')write.frequencyAdded++;else write.frequencyUpdated++;write.auditInserted++}
      if(row.scheduleAction==='Update Frequency'){const s=db.prepare('SELECT * FROM branch_schedules WHERE jodoo_schedule_id=?').get(row.scheduleId);db.prepare('UPDATE branch_schedules SET frequency=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(row.targetFrequency,s.id);const after=db.prepare('SELECT * FROM branch_schedules WHERE id=?').get(s.id);audit(db,'branch_schedule',s.jodoo_schedule_id,'approved_frequency_sync','frequency',s.frequency,row.targetFrequency,s,after,row.excelRow,{branchId:row.branchId,customerId:row.customerId});write.scheduleFrequencyUpdated++;write.auditInserted++}
    }
    for(const d of duplicates.filter(x=>x.safe)){const s=db.prepare('SELECT * FROM branch_schedules WHERE id=?').get(d.deactivateInternalId);if(s.is_active!==1)continue;db.prepare('UPDATE branch_schedules SET is_active=0,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(s.id);const after=db.prepare('SELECT * FROM branch_schedules WHERE id=?').get(s.id);audit(db,'branch_schedule',s.jodoo_schedule_id,'duplicate_schedule_deactivated','is_active','1','0',s,after,null,{branchId:d.branchId,retainedScheduleId:d.keep,deactivatedScheduleId:d.deactivate,identicalVerified:d.identical,dispatchStopRefs:d.dispatchStopRefs,exceptionRefs:d.exceptionRefs});write.duplicateSchedulesDeactivated++;write.auditInserted++}
    const after=counts(db);if(after.customers!==before.customers||after.branches!==before.branches||after.weekdays!==before.weekdays||after.dispatches!==before.dispatches||after.dispatchStops!==before.dispatchStops)throw new Error('Protected count changed');if(db.prepare('PRAGMA foreign_key_check').all().length)throw new Error('Post-write foreign_key_check failed');if(db.prepare('PRAGMA integrity_check').get().integrity_check!=='ok')throw new Error('Post-write integrity_check failed');db.exec('COMMIT');return{mode:'apply',before,after,plan,write,writes:Object.values(write).reduce((a,b)=>a+b,0)}
  }catch(e){db.exec('ROLLBACK');throw e}
}

function main(){const args=process.argv.slice(2),apply=args.includes('--apply'),dbPath=args.find(x=>x.startsWith('--db='))?.slice(5)||process.env.KCS_DB_PATH,inputPath=args.find(x=>x.startsWith('--input='))?.slice(8),log=args.find(x=>x.startsWith('--log='))?.slice(6);if(!dbPath||!inputPath)throw new Error('Use --db=<sqlite> --input=<json> [--apply]');const db=new DatabaseSync(path.resolve(dbPath),{readOnly:!apply});try{const result=runCombinedImport(db,JSON.parse(fs.readFileSync(path.resolve(inputPath),'utf8')),{apply});const output=JSON.stringify({...result,databasePath:path.resolve(dbPath),inputPath:path.resolve(inputPath),actor:ACTOR,completedAt:new Date().toISOString()},null,2);if(log)fs.writeFileSync(path.resolve(log),output);console.log(output)}finally{db.close()}}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url))main()
